import { Bar, ChartLegend, ComparisonLine, Line } from 'components';
import type { ChartLegendItem } from 'components';
import { COMPARISON_TREND_COLORS } from 'components/Chart/lineBarChart';
import { theme } from 'theme';

import {
  PHI_LINE_CHART_Y_AXIS_WIDTH,
  usePhiLineBarChartDatasets,
} from '../../hooks/usePhiLineBarChartDatasets';
import type { PhiOvertimeChartData } from '../../types';
import {
  phiLineComparisonRowConfig,
  StyledBarChartColumn,
  StyledChartsGrid,
  StyledChartWrapper,
  StyledLineChartColumn,
  StyledLineChartWrapper,
  StyledPhiBarChartLegendRow,
} from './PhiLineBarChartsGrid.styles';

export interface PhiLineBarChartsGridProps {
  data: PhiOvertimeChartData;
  legendItems: ChartLegendItem[];
  dataTestId?: string;
}

export const PhiLineBarChartsGrid: React.FC<PhiLineBarChartsGridProps> = ({
  data,
  legendItems,
  dataTestId,
}) => {
  const {
    lineChart,
    barChart,
    lineDatasets,
    barDatasets,
    barOptions,
    lineChartOptions,
    comparisonData,
    lineChartCanvasHeight,
  } = usePhiLineBarChartDatasets(data);

  return (
    <StyledChartsGrid data-testid={dataTestId}>
      <StyledLineChartColumn>
        <StyledLineChartWrapper
          style={{ height: `${lineChartCanvasHeight}px` }}
          data-testid={
            dataTestId ? `${dataTestId}-line-chart-wrapper` : undefined
          }
        >
          <Line
            datasets={lineDatasets}
            labels={lineChart.labels}
            formattedData={lineChart.formattedData}
            labelColors={[theme.colors.txt.secondary, theme.colors.txt.default]}
            showCustomGrid
            showDivider
            options={lineChartOptions}
            dataTestId={
              dataTestId ? `${dataTestId}-overtime-line-chart` : undefined
            }
          />
        </StyledLineChartWrapper>
        {lineChart.comparisonLine && (
          <ComparisonLine
            data={comparisonData}
            gridColumnsLength={lineChart.labels.length}
            gridConfig={{ paddingLeft: 5, paddingRight: 0 }}
            borderConfig={{
              marginLeft: PHI_LINE_CHART_Y_AXIS_WIDTH,
              marginRight: 0,
            }}
            rowConfig={phiLineComparisonRowConfig}
            trendColors={COMPARISON_TREND_COLORS}
            dataTestId={
              dataTestId ? `${dataTestId}-comparison-table` : undefined
            }
          />
        )}
      </StyledLineChartColumn>
      <StyledBarChartColumn
        data-testid={dataTestId ? `${dataTestId}-bar-chart-module` : undefined}
      >
        <StyledPhiBarChartLegendRow>
          <ChartLegend
            items={legendItems}
            dataTestId={dataTestId ? `${dataTestId}-chart-legend` : undefined}
          />
        </StyledPhiBarChartLegendRow>
        <StyledChartWrapper
          style={{ height: `${lineChartCanvasHeight}px` }}
          data-testid={
            dataTestId ? `${dataTestId}-bar-chart-wrapper` : undefined
          }
        >
          <Bar
            datasets={barDatasets}
            labels={barChart.labels}
            formattedData={barChart.formattedData}
            stripedIndexes={barChart.stripedIndexes ?? []}
            size="medium"
            maxSize="none"
            alwaysShowDataLabels
            showGrid={false}
            axisType="none"
            options={barOptions}
            dataTestId={dataTestId ? `${dataTestId}-benchmark-bars` : undefined}
          />
        </StyledChartWrapper>
      </StyledBarChartColumn>
    </StyledChartsGrid>
  );
};
